-- Historical snapshot basis: reports/2026-11-12-gap-event-catalog.csv.
-- This query does not assert those slots were expected; source matches are review candidates only.
WITH targets AS (SELECT 1548076500 AS left_time, 1548077100 AS right_time, '2019:1548076500:1548077100' AS gap_id, 600 AS gap_seconds, 'lt_1h' AS gap_band UNION ALL SELECT 1556184300, 1556185500, '2019:1556184300:1556185500', 1200, 'lt_1h' UNION ALL SELECT 1557825600, 1557826200, '2019:1557825600:1557826200', 600, 'lt_1h' UNION ALL SELECT 1557828300, 1557828900, '2019:1557828300:1557828900', 600, 'lt_1h' UNION ALL SELECT 1557840000, 1557840600, '2019:1557840000:1557840600', 600, 'lt_1h' UNION ALL SELECT 1558259700, 1558341000, '2019:1558259700:1558341000', 81300, '1h_to_lt_1d' UNION ALL SELECT 1559203200, 1559208900, '2019:1559203200:1559208900', 5700, '1h_to_lt_1d' UNION ALL SELECT 1559209500, 1559213700, '2019:1559209500:1559213700', 4200, '1h_to_lt_1d' UNION ALL SELECT 1559214300, 1559216400, '2019:1559214300:1559216400', 2100, 'lt_1h' UNION ALL SELECT 1559217600, 1559218500, '2019:1559217600:1559218500', 900, 'lt_1h' UNION ALL SELECT 1559219100, 1559223300, '2019:1559219100:1559223300', 4200, '1h_to_lt_1d' UNION ALL SELECT 1559223900, 1559224800, '2019:1559223900:1559224800', 900, 'lt_1h' UNION ALL SELECT 1559239500, 1559240100, '2019:1559239500:1559240100', 600, 'lt_1h' UNION ALL SELECT 1559293500, 1559294100, '2019:1559293500:1559294100', 600, 'lt_1h' UNION ALL SELECT 1559295300, 1559295900, '2019:1559295300:1559295900', 600, 'lt_1h' UNION ALL SELECT 1559295900, 1559296500, '2019:1559295900:1559296500', 600, 'lt_1h' UNION ALL SELECT 1559296800, 1559297400, '2019:1559296800:1559297400', 600, 'lt_1h' UNION ALL SELECT 1559297400, 1559298000, '2019:1559297400:1559298000', 600, 'lt_1h' UNION ALL SELECT 1559298600, 1559299500, '2019:1559298600:1559299500', 900, 'lt_1h' UNION ALL SELECT 1559299500, 1559300100, '2019:1559299500:1559300100', 600, 'lt_1h' UNION ALL SELECT 1559300100, 1559300700, '2019:1559300100:1559300700', 600, 'lt_1h' UNION ALL SELECT 1559301300, 1559301900, '2019:1559301300:1559301900', 600, 'lt_1h' UNION ALL SELECT 1559733900, 1559734500, '2019:155